#!/system/bin/sh
# 安装时按本机现有 plat_mac_permissions.xml 重建一份（ROM 升级后也不会错配），
# 追加 PipDesk 签名证书 → seinfo=platform，使 uid 1000 的应用能拿到 system_app 域。
command -v ui_print >/dev/null 2>&1 || ui_print() { echo "$@"; }

SIGNER=""
SRC=/system/etc/selinux/plat_mac_permissions.xml
DST=$MODPATH/system/etc/selinux/plat_mac_permissions.xml

ui_print "- 注入 PipDesk 证书 → seinfo=platform"
mkdir -p $MODPATH/system/etc/selinux
if [ -f "$SRC" ]; then
  cp -f "$SRC" "$DST"
  if ! grep -q "$SIGNER" "$DST"; then
    sed -i "s|</policy>|<signer signature=\"$SIGNER\"><seinfo value=\"platform\"/></signer></policy>|" "$DST"
  fi
fi
if grep -q "$SIGNER" "$DST" 2>/dev/null; then
  ui_print "- mac_permissions 注入成功（共 $(grep -o '<signer ' $DST | wc -l) 个签名者）"
else
  ui_print "! 注入失败：将使用模块内预置文件"
fi
set_perm_recursive $MODPATH/system/priv-app 0 0 0755 0644
